    """Return a closed chain using every domino, or None if none exists."""
    stones = list(dominoes)
    if not stones:
        return []

    adjacency = {}
    for edge_id, (left, right) in enumerate(stones):
        adjacency.setdefault(left, []).append((right, edge_id))
        adjacency.setdefault(right, []).append((left, edge_id))

    # Every visit to a value in a closed chain must also leave that value.
    if any(len(edges) % 2 for edges in adjacency.values()):
        return None

    used = set()
    stack = [stones[0][0]]
    circuit = []
    while stack:
        edges = adjacency[stack[-1]]
        while edges and edges[-1][1] in used:
            edges.pop()
        if edges:
            neighbor, edge_id = edges.pop()
            used.add(edge_id)
            stack.append(neighbor)
        else:
            circuit.append(stack.pop())

    # Even degrees are not enough: all stones must belong to one component.
    if len(used) != len(stones):
        return None

    circuit.reverse()
    return list(zip(circuit, circuit[1:]))
